#!/usr/bin/env python3
"""
Round 213o (culprits-tiles-more), 15 October 2026. Needs round210o_tiles.py.

- sun.py: reads the names on Wikipedia's List of active Solar System probes
  (CC BY-SA 4.0) and marks the Heliocentric Register rows of those craft
  (and parts still attached) as "active", so the map can leave out the craft
  still working. Every row is still written; the run log lists the names read
  and the rows marked.
- reach.py: the List of nearest stars' distances and positions are read now
  (its column is written "Dis-tance" with a soft hyphen, and its positions as
  "14 29 43.0 -62 40 46"); the GM of the dwarf planets is read only from
  Horizons' own "GM=" or "GM, km^3/s^2 =" and kept beside the line it came
  from (gm_as_written).

Afterwards run refresh with reach, then with sun.
Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/reach.py': '', 'scripts/sun.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round213o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round213o_tiles: wrote {path}")
    if not changed:
        print("round213o_tiles: already applied")


if __name__ == "__main__":
    main()
